146	describe('Scope probe cleanup', () => {
147	  it('should clean up every created resource exactly once and read the results back after recreating the app', async () => {
148	    const before = ProbeCleanupStore.snapshot();
149	
150	    const firstApp = await createApp();
151	    const firstUrl = await firstApp.getUrl();
152	
153	    const firstResponses = await Promise.all([
154	      request(firstUrl).get('/scope-probe').query({ marker: 'one' }),
155	      request(firstUrl).get('/scope-probe').query({ marker: 'two' }),
156	      request(firstUrl).get('/scope-probe').query({ marker: 'three' }),
157	    ]);
158	    const firstSingletonId = firstResponses[0].body.singletonId;
159	
160	    // A request racing the shutdown must not change the per-resource counts.
161	    let racedRequestCompleted = false;
162	    const inFlight = request(firstUrl)
163	      .get('/scope-probe')
164	      .query({ marker: 'race' })
165	      .then(() => {
166	        racedRequestCompleted = true;
167	      })
168	      .catch(() => undefined);
169	
170	    await firstApp.close();
171	    await inFlight;
172	    // Repeated close must not clean any resource twice.
173	    await firstApp.close();
174	
175	    const completedRequests = 3 + (racedRequestCompleted ? 1 : 0);
176	    const afterClose = ProbeCleanupStore.snapshot();
177	    expect(afterClose.request - before.request).toBe(completedRequests);
178	    expect(afterClose.transient - before.transient).toBe(completedRequests * 2);
179	    expect(afterClose.singleton - before.singleton).toBe(1);
180	
181	    // The closed application must not serve the probe anymore.
182	    await expect(
183	      fetch(`${firstUrl}/scope-probe?marker=closed`),
184	    ).rejects.toThrow();
185	
