220	        NestFactory.create(brokenModule, {
221	          logger: false,
222	          abortOnError: false,
223	        }),
224	      ).rejects.toThrow();
225	
226	      const app = await createApp();
227	      try {
228	        const response = await request(await app.getUrl())
229	          .get('/scope-probe')
