/**
 * Lifecycle of a single snapshot registration, as observed through the
 * `/context-records` probe.
 *
 * - `open`      - the request has not terminated yet, no snapshot exists;
 * - `frozen`    - the request terminated and the snapshot was captured, but
 *                 the post-response callback has not run;
 * - `completed` - the callback has run exactly once against the frozen
 *                 snapshot.
 */
export type ProbeRecordState = 'open' | 'frozen' | 'completed';

/** Read-only projection of a registration. */
export interface ProbeRecord {
  /** Unique per registration: equal markers never merge records. */
  id: string;
  marker: string;
  state: ProbeRecordState;
  /**
   * Values visible to consumers of the owning request. `null` until the
   * snapshot is frozen.
   */
  frozenValue: string | null;
  /** Value the callback observed, or `null` until it ran. */
  callbackValue: string | null;
  /** Error message when the callback failed, `null` otherwise. */
  callbackError: string | null;
  /** How many times the snapshot was terminated (guarded to stay at 1). */
  finalizations: number;
  /** How many times the callback ran (guarded to stay at 1). */
  callbackRuns: number;
}

