   * Frozen on termination; later writes never reach this object.
   */
  readonly values: Readonly<Record<string, string>>;
  /** Why the request terminated. */
  readonly reason: 'finish' | 'aborted' | 'error';
  readonly terminatedAt: number;
}

/**
 * Mutable per-request bag that becomes a {@link RequestSnapshot} exactly
 * once. A single instance is stashed on the request, so every consumer of a
 * request shares the same host even when marker strings collide across
 * concurrent requests.
 */
export class RequestSnapshotHost {
  private state: ProbeRecordState = 'open';
  private finalizations = 0;
  private snapshot: RequestSnapshot | null = null;
  private terminationCallbacks: SnapshotCallback[] = [];
  private readonly values: Record<string, string> = {};
  /** Reads already performed by a callback, asserted to stay consistent. */
  private callbackReads = 0;

  constructor(
    readonly requestId: string,
    readonly marker: string,
  ) {}

  get isFrozen(): boolean {
    return this.state !== 'open';
  }

  /**
   * Writes a value for the owning request. Before termination every consumer
   * sees it; after termination it is ignored so the frozen snapshot can never
   * change.
   */
  setValue(key: string, value: string): boolean {
    if (this.isFrozen) {
      return false;
    }
    this.values[key] = value;
    return true;
  }

  getValue(key: string): string | undefined {
    const source = this.isFrozen ? this.snapshot!.values : this.values;
    return source[key];
  }

  /** Registers work to run after termination. Idempotently guarded. */
  onTerminated(callback: SnapshotCallback): void {
    this.terminationCallbacks.push(callback);
  }

  /**
   * Freezes the snapshot. Safe to invoke repeatedly (finish + close + error
   * can all fire for one request): only the first call terminates.
   *
   * Returns the frozen snapshot, or the existing one on repeated calls.
   */
  finalize(reason: RequestSnapshot['reason']): RequestSnapshot {
    this.finalizations++;
