    return this.snapshot;
  }

  getFinalizationCount(): number {
    return this.finalizations;
  }

  getState(): ProbeRecordState {
    return this.state;
  }

  getSnapshot(): RequestSnapshot | null {
    return this.snapshot;
  }

  /**
   * Runs the pending callbacks once. Every callback receives the same frozen
   * snapshot instance; repeated reads stay identical even when the request
   * objects are gone.
   */
  async runCallbacks(): Promise<void> {
    const callbacks = this.terminationCallbacks;
    this.terminationCallbacks = [];
