      // tracks a second read externally for the consistency assertion.
      this.callbackReads = before + 1;
    }
    if (callbacks.length > 0) {
      this.state = 'completed';
    }
  }

  getCallbackRunCount(): number {
    return this.callbackReads;
  }
}

