import { Injectable, type NestMiddleware } from '@nestjs/common';
import { RequestContextRegistry } from './request-context.registry.js';

/**
 * Attaches a per-request snapshot host and wires its termination. Runs for
 * every route so the capability is available to any consumer, but only
 * explicit registrations create records.
 */
@Injectable()
export class SnapshotContextMiddleware implements NestMiddleware {
  constructor(private readonly registry: RequestContextRegistry) {}

  use(req: any, res: any, next: () => void): void {
    this.registry.attach(req, res);
    next();
  }
}

import {
  type CallHandler,
  type ExecutionContext,
  Injectable,
  type NestInterceptor,
} from '@nestjs/common';
import { map, type Observable } from 'rxjs';
import {
  REQUEST_SNAPSHOT_HOST,
  RequestContextRegistry,
} from './request-context.registry.js';

/**
 * Another consumer of the same request's context: it writes a value before
 * the response terminates, so post-response callbacks must observe the value
 * in the frozen snapshot.
 */
@Injectable()
export class SnapshotConsumerInterceptor implements NestInterceptor {
  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<unknown> {
    const req = context.switchToHttp().getRequest();
    req[REQUEST_SNAPSHOT_HOST]?.setValue('interceptor', 'saw-request');
    return next.handle().pipe(map(data => data));
  }
}

import { Injectable } from '@nestjs/common';

/**
 * Allows a probe request to be held open deliberately, so tests can observe
 * the `open` (not yet terminated) state through `/context-records`.
 */
@Injectable()
export class ProbeHoldService {
  private readonly waiters = new Map<string, () => void>();

  wait(marker: string): Promise<void> {
    return new Promise(resolve => {
      this.waiters.set(marker, resolve);
    });
  }

  release(marker: string): boolean {
    const resolve = this.waiters.get(marker);
    if (!resolve) {
      return false;
    }
    this.waiters.delete(marker);
    resolve();
    return true;
  }
}

